function ds(n){return String(n).split('').reduce(function(a,b){return a+ +b;},0);}
function greer(d,m,y){var s=d+m+y;var n=ds(s);while(n>22)n=ds(n);var r=[n];if(n===19)r=[19,10,1];else if(n>9){var k=ds(n);r=[n,k];}return {sum:s,n:n,cards:r};}
